                                  return Container(
                                    color: surfaceColor,
                                    child: Stack(
                                      fit: StackFit.expand,
                                      alignment: Alignment.center,
                                      children: [
                                        if (thumbnailPath != null)
                                          Image.file(
                                            File(thumbnailPath),
                                            fit: BoxFit.cover,
                                            errorBuilder: (_, __, ___) {
                                              return const ColoredBox(
                                                color: surfaceColor,
                                                child: Icon(
